-- tokyo: checked place by place on 2026-10-25 (still open, own websites, prices with sources).

UPDATE "Place" p SET "website" = 'https://www.gate-hotel.jp/tokyo/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'gate-hotel';
UPDATE "Place" p SET "website" = 'https://unplan.jp/shinjuku?lang=ja' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'unplan-shinjuku';
UPDATE "Place" p SET "name" = 'MAG8 rooftop at Magnet by Shibuya109' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'magnet-shibuya109';
UPDATE "Place" p SET "website" = 'https://www.billsjapan.com/en/locations/omotesando' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'bills-omotesando';
