-- Two places in one stop: now two places and two stops.
UPDATE "Place" p SET "slug" = 'yasukuni-shrine', "name" = 'Yasukuni Shrine', "blurb" = 'Shrine founded in 1869 to Japan''s war dead, politically controversial.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'yasukuni';
INSERT INTO "Place" ("id", "slug", "name", "category", "area", "blurb", "lat", "lng", "checkedAt", "destinationId") SELECT 'tokyo-yushukan', 'yushukan', 'Yushukan museum', 'EXPERIENCE', 'Kudanshita', 'Military history museum in the Yasukuni Shrine grounds.', 35.6948, 139.7428, '2026-10-25', d.id FROM "Destination" d WHERE d.slug = 'tokyo' ON CONFLICT DO NOTHING;
UPDATE "Item" i SET "name" = 'Yasukuni Shrine', "priceCents" = 0, "priceNote" = 'free', "priceSourceUrl" = NULL FROM "Place" p JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' WHERE p.id = i."placeId" AND p.slug = 'yasukuni-shrine';
UPDATE "Item" i SET "position" = i."position" + 1 FROM "Item" a JOIN "Place" p ON p.id = a."placeId" AND p.slug = 'yasukuni-shrine' JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' WHERE i."itineraryId" = a."itineraryId" AND i."position" > a."position";
INSERT INTO "Item" ("id", "day", "position", "name", "category", "priceCents", "priceNote", "itineraryId", "placeId") SELECT it.slug || '--yushukan', a."day", a."position" + 1, 'Yushukan museum', 'EXPERIENCE', 632, 'creator: 1,000 JPY', a."itineraryId", n.id FROM "Item" a JOIN "Place" p ON p.id = a."placeId" AND p.slug = 'yasukuni-shrine' JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' JOIN "Itinerary" it ON it.id = a."itineraryId" JOIN "Place" n ON n.slug = 'yushukan' AND n."destinationId" = d.id ON CONFLICT DO NOTHING;
UPDATE "Place" p SET "slug" = 'daikanyama', "name" = 'Daikanyama', "blurb" = 'Laid-back neighbourhood south of Shibuya with boutiques, cafés and the T-Site bookshop.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'tokyo' AND p.slug = 'daikanyama-ebisu';
INSERT INTO "Place" ("id", "slug", "name", "category", "area", "blurb", "lat", "lng", "checkedAt", "destinationId") SELECT 'tokyo-ebisu', 'ebisu', 'Ebisu', 'EXPERIENCE', 'Ebisu', 'Neighbourhood around Ebisu Station, known for its restaurants and bars.', 35.6467, 139.7101, '2026-10-25', d.id FROM "Destination" d WHERE d.slug = 'tokyo' ON CONFLICT DO NOTHING;
UPDATE "Item" i SET "name" = 'Shibuya & Daikanyama', "priceCents" = 0, "priceNote" = 'free', "priceSourceUrl" = NULL FROM "Place" p JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' WHERE p.id = i."placeId" AND p.slug = 'daikanyama';
UPDATE "Item" i SET "position" = i."position" + 1 FROM "Item" a JOIN "Place" p ON p.id = a."placeId" AND p.slug = 'daikanyama' JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' WHERE i."itineraryId" = a."itineraryId" AND i."position" > a."position";
INSERT INTO "Item" ("id", "day", "position", "name", "category", "priceCents", "priceNote", "itineraryId", "placeId") SELECT it.slug || '--ebisu', a."day", a."position" + 1, 'Ebisu', 'EXPERIENCE', 0, 'free', a."itineraryId", n.id FROM "Item" a JOIN "Place" p ON p.id = a."placeId" AND p.slug = 'daikanyama' JOIN "Destination" d ON d.id = p."destinationId" AND d.slug = 'tokyo' JOIN "Itinerary" it ON it.id = a."itineraryId" JOIN "Place" n ON n.slug = 'ebisu' AND n."destinationId" = d.id ON CONFLICT DO NOTHING;
